INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m6-005', 'c1-m6-i5', 'calculus-1', 'c1-m6', 0, '小测：面积元素', '由 \\( y=f(x)\\ge0 \\)、\\( x=a \\)、\\( x=b \\) 与 \\( x \\) 轴围成的曲边梯形面积为（ ）', '["\\\\( \\\\displaystyle\\\\int_a^b f(x)\\\\,dx \\\\)","\\\\( \\\\displaystyle\\\\int_a^b f^{\\\\prime}(x)\\\\,dx \\\\)","\\\\( \\\\displaystyle\\\\int_b^a f(x)\\\\,dx \\\\)","\\\\( f(b)-f(a) \\\\)"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '面积为 \\( \\int_a^b f(x)\\,dx \\)。', NULL, NULL, NULL, 2, '["面积"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
