INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m1-005', 'c2-m1-i4', 'calculus-2', 'c2-m1', 0, '空间曲线方程', '空间曲线的一般方程可用 __________ 个曲面方程联立表示。', '["三","两","四","一"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '空间曲线可看作两个曲面的交线，故用两个方程联立表示。', NULL, NULL, NULL, 2, '["空间曲线"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m1-006', 'c2-m1-i5', 'calculus-2', 'c2-m1', 0, '平面方程', '求过点 \\( (1,0,0) \\) 且法向量为 \\( (1,1,1) \\) 的平面方程（写成“x+y+z=1”形式）。', '["x+y+z=1","x+y+z=-1","x+y+z=0","选项1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '点法式：\\( 1(x-1)+1(y-0)+1(z-0)=0 \\)，即 \\( x+y+z=1 \\)。', NULL, NULL, NULL, 2, '["平面"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
