INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m2-004', 'c2-m2-i3', 'calculus-2', 'c2-m2', 0, '全微分', '设 \\( z=x^2+y^2 \\)，求全微分 \\( dz \\)（写成“2xdx+2ydy”）。', '["2xdx+2ydy+1","2xdx+2ydy","2xdx-2ydy","2xdx+2ydy-1"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '\\( dz=\\frac{\\partial z}{\\partial x}dx+\\frac{\\partial z}{\\partial y}dy=2x\\,dx+2y\\,dy \\)。', NULL, NULL, NULL, 2, '["全微分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m2-005', 'c2-m2-i4', 'calculus-2', 'c2-m2', 0, '复合函数求导', '设 \\( z=\\sin u \\)，\\( u=x^2+y \\)，求 \\( \\frac{\\partial z}{\\partial x} \\)。', '["2xsin(x^2+y)","2xcos(x^2+y)","2xcos(x^2+y)+1","2xcos(x^2-y)"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '链式法则：\\( \\frac{\\partial z}{\\partial x}=\\cos u\\cdot2x \\)。', NULL, NULL, NULL, 2, '["复合函数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m2-006', 'c2-m2-i5', 'calculus-2', 'c2-m2', 0, '隐函数求导', '由 \\( x^2+y^2+z^2=1 \\) 确定的隐函数 \\( z=z(x,y) \\)，求 \\( \\frac{\\partial z}{\\partial x} \\) 在 \\( (0,0,1) \\) 处的值。', '["-1","2","1","0"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '两边对 \\( x \\) 求偏导：\\( 2x+2z z_x=0 \\)，代入得 \\( z_x=0 \\)。', NULL, NULL, NULL, 2, '["隐函数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m2-007', 'c2-m2-i6', 'calculus-2', 'c2-m2', 0, '曲面的切平面', '曲面 \\( z=f(x,y) \\) 在点 \\( (x_0,y_0,z_0) \\) 处的切平面方程中，法向量为 \\( (f_x,f_y,\\)__________\\() \\)。', '["-2","0","1","-1"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '切平面法向量可取 \\( (f_x,f_y,-1) \\)。', NULL, NULL, NULL, 2, '["几何应用"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m2-008', 'c2-m2-i7', 'calculus-2', 'c2-m2', 0, '方向导数', '设 \\( f(x,y)=x^2+y^2 \\)，求在点 \\( (1,0) \\) 沿方向 \\( (1,0) \\) 的方向导数。', '["2","4","3","1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '梯度 \\( \\nabla f=(2x,2y) \\)，方向导数 \\( \\nabla f\\cdot(1,0)=2 \\)。', NULL, NULL, NULL, 2, '["方向导数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m2-009', 'c2-m2-i8', 'calculus-2', 'c2-m2', 0, '无条件极值', '求 \\( f(x,y)=x^2+y^2 \\) 的极小值。', '["2","0","-1","1"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '显然在 \\( (0,0) \\) 取得最小值 0。', NULL, NULL, NULL, 2, '["极值"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m2-010', 'c2-m2-i9', 'calculus-2', 'c2-m2', 0, '多元微分综合', '设 \\( z=\\ln(x^2+y^2) \\)，求 \\( \\frac{\\partial z}{\\partial x} \\)。', '["2x/(x^2-y^2)","2x/(x^2+y^2)","2x/(x^2+y^2)-1","2x/(x^2+y^2)+1"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '链式法则。', NULL, NULL, NULL, 2, '["偏导数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m2-011', 'c2-m2-i10', 'calculus-2', 'c2-m2', 0, '小测：可微与偏导', '二元函数在某点可微是该点偏导数存在的（ ）', '["充分非必要条件","必要非充分条件","充分必要条件","无关条件"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '可微必偏导存在，反之不成立，故为充分非必要条件。', NULL, NULL, NULL, 2, '["多元函数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m3-001', 'c2-m3-i1', 'calculus-2', 'c2-m3', 0, '二重积分概念', '设 \\( D \\) 为矩形 \\( [0,1]\\times[0,1] \\)，求 \\( \\displaystyle\\iint_D 1\\,d\\sigma \\)。', '["0","-1","1","2"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '积分值为区域面积 \\( 1 \\)。', NULL, NULL, NULL, 2, '["二重积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m3-002', 'c2-m3-i2', 'calculus-2', 'c2-m3', 0, '直角坐标计算二重积分', '求 \\( \\displaystyle\\iint_D (x+y)\\,d\\sigma \\)，其中 \\( D:0\\le x\\le1,0\\le y\\le1 \\)。', '["0","2","-1","1"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '\\( \\int_0^1\\int_0^1(x+y)\\,dy\\,dx=1 \\)。', NULL, NULL, NULL, 2, '["二重积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m3-003', 'c2-m3-i2', 'calculus-2', 'c2-m3', 0, '极坐标二重积分', '求 \\( \\displaystyle\\iint_D e^{-x^2-y^2}\\,d\\sigma \\)，其中 \\( D \\) 为圆域 \\( x^2+y^2\\le1 \\)。', '["0","1.98586","1.985865","2.98586"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '极坐标：\\( \\int_0^{2\\pi}\\int_0^1 e^{-r^2}r\\,dr\\,d\\theta=\\pi(1-e^{-1}) \\)。', NULL, NULL, NULL, 2, '["二重积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m3-004', 'c2-m3-i3', 'calculus-2', 'c2-m3', 0, '三重积分', '求 \\( \\displaystyle\\iiint_\\Omega 1\\,dV \\)，其中 \\( \\Omega \\) 为单位球 \\( x^2+y^2+z^2\\le1 \\)。', '["5.18879","0","4.18879","3.18879"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '体积 \\( \\frac43\\pi \\)。', NULL, NULL, NULL, 2, '["三重积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m3-005', 'c2-m3-i4', 'calculus-2', 'c2-m3', 0, '质心', '设均匀薄板 \\( D \\) 为圆盘 \\( x^2+y^2\\le R^2 \\)，求其质心的 \\( x \\) 坐标。', '["1","0","-1","2"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '对称性得 \\( \\bar x=0 \\)。', NULL, NULL, NULL, 2, '["重积分应用"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m3-006', 'c2-m3-i5', 'calculus-2', 'c2-m3', 0, '重积分综合', '求 \\( \\displaystyle\\iint_D xy\\,d\\sigma \\)，其中 \\( D \\) 为 \\( [0,1]\\times[0,1] \\)。', '["-0.75","1.25","0.25","0"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( \\int_0^1 x\\,dx\\cdot\\int_0^1 y\\,dy=\\frac14 \\)。', NULL, NULL, NULL, 2, '["二重积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m4-001', 'c2-m4-i1', 'calculus-2', 'c2-m4', 0, '对弧长的曲线积分', '计算 \\( \\displaystyle\\int_L (x+y)\\,ds \\)，其中 \\( L \\) 为从 \\( (0,0) \\) 到 \\( (1,1) \\) 的直线段。', '["0","1.41421","1.414214","2.41421"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '参数化 \\( x=y=t \\)，\\( ds=\\sqrt2\\,dt \\)，积分 \\( \\sqrt2\\int_0^1 2t\\,dt=\\sqrt2 \\)。', NULL, NULL, NULL, 2, '["曲线积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m4-002', 'c2-m4-i2', 'calculus-2', 'c2-m4', 0, '对坐标的曲线积分', '计算 \\( \\displaystyle\\int_L x\\,dy-y\\,dx \\)，其中 \\( L \\) 为从 \\( (0,0) \\) 到 \\( (1,1) \\) 沿 \\( y=x \\) 的线段。', '["0","1","2","-1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '参数化 \\( x=t,y=t \\)，得 \\( \\int_0^1(t-t)\\,dt=0 \\)。', NULL, NULL, NULL, 2, '["曲线积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m4-003', 'c2-m4-i3', 'calculus-2', 'c2-m4', 0, '格林公式', '设 \\( L \\) 为圆周 \\( x^2+y^2=1 \\) 取正向，用格林公式求 \\( \\displaystyle\\oint_L x\\,dy-y\\,dx \\)。', '["0","7.28318","6.283185","6.28318"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( \\iint_D(1-(-1))\\,d\\sigma=2\\pi \\)。', NULL, NULL, NULL, 2, '["格林公式"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m4-004', 'c2-m4-i4', 'calculus-2', 'c2-m4', 0, '对面积的曲面积分', '计算 \\( \\displaystyle\\iint_\\Sigma 1\\,dS \\)，其中 \\( \\Sigma \\) 为球面 \\( x^2+y^2+z^2=1 \\)。', '["13.5664","12.5664","11.5664","12.566371"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '球面面积 \\( 4\\pi \\)。', NULL, NULL, NULL, 2, '["曲面积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
