INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-2-c2-m4-007', 'c2-m4-i7', 'calculus-2', 'c2-m4', 0, '曲线积分综合', '判断 \\( \\displaystyle\\int_L (2xy+1)\\,dx+x^2\\,dy \\) 是否与路径无关。', '["无关","相关","线性相关","线性无关"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '\\( \\frac{\\partial Q}{\\partial x}=2x=\\frac{\\partial P}{\\partial y} \\)，且区域为单连通，故与路径无关。', NULL, NULL, NULL, 2, '["曲线积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
