INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-009', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 9 题', '如图所示，一个小物体，位于光滑的水平桌面上，与一绳的一端相连结，绳的另一端穿过桌面中心的小孔O. 该物体原以角速度ω在半径为R的圆周上绕O旋转，今将绳从小孔缓慢往下拉．则物体', '["动能不变，动量改变;","动量不变，动能改变;","角动量不变，动量不变;","角动量改变，动量改变;","角动量不变，动能、动量都改变"]'::jsonb, '4', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q009.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-010', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 10 题', '人造地球卫星，绕地球作椭圆轨道运动，地球在椭圆的一个焦点上，则卫星的', '["动量不守恒，动能守恒","动量守恒，动能不守恒","对地心的角动量守恒，动能不守恒","对地心的角动量不守恒，动能守恒"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-011', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 11 题', '一圆盘绕过盘心且与盘面垂直的光滑固定轴O以角速度ω按图示方向转动.若如图所示的情况那样，将两个大小相等方向相反但不在同一条直线的力F沿盘面同时作用到圆盘上，则圆盘的角速度', '["必然增大;","必然减少;","不会改变;","如何变化，不能确定"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q011.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-012', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 12 题', '均匀细棒OA可绕通过其一端O而与棒垂直的水平固定光滑轴转动，如图所示．今使棒从水平位置由静止开始自由下落，在棒摆动到竖直位置的过程中，下述说法哪一种是正确的？', '["角速度从小到大，角加速度从大到小;","角速度从小到大，角加速度从小到大;","角速度从大到小，角加速度从大到小;","角速度从大到小，角加速度从小到大"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q012.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-013', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 13 题', '图(a)为一绳长为l 、质量为m 的单摆。图(b)为一长度为l、质量m为能绕水平固定轴O自由转动的匀质细棒。现将单摆和细棒同时从与竖直线成θ 角度的位置由静止释放。若运动到竖直位置时，单摆、细棒角速度分别以 $\\omega_{1}, \\ \\omega_{2}$ 表示。则：', '["$\\\\omega_{1}{=}2 \\\\omega_{2}$","$\\\\omega_{1}{=}\\\\omega_{2}$","$\\\\omega_{1}=\\\\frac{2}{3}\\\\omega_{2}$","${\\\\omega}_{1}=\\\\sqrt{\\\\frac{2}{3}}\\\\,{\\\\omega}_{2}$"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q013.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-014', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 14 题', '一轻绳跨过一具有水平光滑轴、质量为的定滑轮，绳的两端分别悬有质量为 $m_{1}$ 和 $m_{2}$ 的物体 $( m_{1}<m_{2})$ ，如图所示。绳与轮之间无相对滑动。若某时刻滑轮沿逆时针方向转动，则绳中的张力', '["处处相等","左边大于右边","右边大于左边","哪边大无法判断"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q014.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-015', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 15 题', '一自由悬挂的匀质细棒 AB，可绕 A 端在竖直平面内自由转动，现给 B 端一初速$\\mathbf{V}_{0},$ ，则棒在向上转动过程中仅就大小而言', '["角速度不断减小，角加速度不断减少","角速度不断减小，角加速度不断增加","角速度不断减小，角加速度不变","所受力矩越来越大，角速度也越来越大"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-016', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 16 题', '一长为l，质量为m 的匀质细棒，绕一端作匀速转动，其中心处的速率为v，则细棒的转动动能为', '["$\\\\mathrm{m}\\\\mathrm{v}^{2}/2$","$2 \\\\mathrm{mv}^{2}/3$","$\\\\mathrm{m}\\\\mathrm{v}^{2}/6$","$\\\\mathrm{mv}^{2}/24$"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-017', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 17 题', '光滑的水平桌面上，有一长为 2L、质量为m的匀质细杆，可绕过其中点且垂直于杆的竖直光滑固定轴O自由转动，其转动惯量为 $\\frac{1}{3}mL^{2}$ ，起初杆静止．桌面上有两个质量均为m的小球，各自在垂直于杆的方向上，正对着杆的一端，以相同速率v相向运动，如图所示．当两小球同时与杆的两个端点发生完全非弹性碰撞后，就与杆粘在一起转动，则这一系统碰撞后的转动角速度应为', '["$\\\\frac{2v}{3 L}$","$\\\\frac{4v}{5 L}$","$\\\\frac{6v}{7 L}$","$\\\\frac{8v}{9 L}$ 俯视图"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q017.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-018', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 18 题', '质点的运动方程 $\\vec{r}=\\left( t-\\frac{t^{2}}{2}\\right) \\vec{i}+\\left( 5-3 t+\\frac{t^{3}}{3}\\right) \\vec{j}$ (SI)，当 $t=2\\,\\mathrm{s}$ 时，其加速度 $\\vec{a}=$', '[]'::jsonb, '$10\\vec i+18\\vec j\\ \\mathrm{m/s^2}$', '[]'::jsonb, NULL, NULL, NULL, '对 $\\vec r$ 求二阶导数：$\\vec a=\\frac{\\mathrm d^2\\vec r}{\\mathrm dt^2}=10\\vec i+9t\\vec j$；代入 $t=2\\,\\mathrm{s}$ 得 $\\vec a=10\\vec i+18\\vec j\\ \\mathrm{m/s^2}$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-019', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 19 题', '在如图所示的装置中，两个定滑轮与绳的质量以及滑轮与其轴之间的摩擦都可忽略不计，绳子不可伸长， $m_{1}$ 与平面之间的摩擦也可不计，在水平外力 F 的作用下，物体 $m_{1}$ 与 $m_{2}$ 的加速度 a＝ _，绳中的张力 T＝', '[]'::jsonb, '$\\frac{F}{m_1+m_2}$; $\\frac{m_2F}{m_1+m_2}$', '[]'::jsonb, NULL, NULL, NULL, '整体：$F=(m_1+m_2)a$，得 $a=F/(m_1+m_2)$。对 $m_2$：$T=m_2a=m_2F/(m_1+m_2)$。', NULL, NULL, '/physics/q019.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-020', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 20 题', '质量为 m 子弹以速度 $v_{0}$ 水平射入沙土中，设子弹所受阻力与速度成正比，比例系数为 k，忽略子弹的重力，求：(1)子弹射入沙土后,速度随时间变化的函数关系式 _；(2)子弹射入沙土的最大深度。', '[]'::jsonb, '$v=v_0e^{-kt/m}$; $\\frac{mv_0}{k}$', '[]'::jsonb, NULL, NULL, NULL, '由 $m\\frac{dv}{dt}=-kv$ 积分得 $v=v_0e^{-kt/m}$。最大深度 $x=\\int_0^\\infty v\\,dt=mv_0/k$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-021', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 21 题', '一颗子弹在枪筒里前进时所受的合力大小为 $F=400-\\frac{4\\times10^{5}}{3}t$ (SI) ，子弹从枪口射出时的速率为 300 m/s。假设子弹离开枪口时合力刚好为零，则 (1)子弹走完枪筒全长所用的时间t = _； (2)子弹在枪筒中所受力的冲量I =； (3)子弹的质量m= 。', '[]'::jsonb, '$3\\times10^{-3}\\ \\mathrm{s}$; $0.6\\ \\mathrm{N\\cdot s}$; $2\\ \\mathrm{g}$', '[]'::jsonb, NULL, NULL, NULL, '令 $F=0$ 得 $t=3\\times10^{-3}\\,\\mathrm{s}$。冲量 $I=\\int_0^t F\\,dt=400t-\\frac{2\\times10^5}{3}t^2=0.6\\,\\mathrm{N\\cdot s}$。由 $I=mv$ 得 $m=I/v=0.002\\,\\mathrm{kg}=2\\,\\mathrm{g}$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-022', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 22 题', '在半径为R的圆周上运动的质点，其速率与时间关系为 $v=c t^{2}$ (式中c为常量)，则从t=0到t时刻质点走过的路程S(t) _； 时刻质点的切向加速度$a_{t}{=}$ ； 时刻质点的法向加速度 $a_{n}=$ 。', '[]'::jsonb, '$\\frac{1}{3}ct^3$; $2ct$; $\\frac{c^2t^4}{R}$', '[]'::jsonb, NULL, NULL, NULL, '$S=\\int_0^t ct''^2\\,dt''=ct^3/3$；$a_t=dv/dt=2ct$；$a_n=v^2/R=c^2t^4/R$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-023', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 23 题', '一质量为m的小球A，在距离地面某一高度处以速度v 水平抛出，触地后反跳．在抛出t秒后小球A跳回原高度，速度仍沿水平方向，速度大小也与抛出时相同，如图．则小球A与地面碰撞过程中，地面给它的冲量的方向为 _，冲量的大小为_', '[]'::jsonb, '竖直向上; $mgt$', '[]'::jsonb, NULL, NULL, NULL, '水平动量不变，竖直方向动量由 $-mv_y$ 变为 $+mv_y$，而上升时间 $t/2$ 对应 $v_y=g t/2$，故竖直冲量 $I_y=2mv_y=mgt$，方向竖直向上。', NULL, NULL, '/physics/q023.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-024', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 24 题', '如图所示，一质量为 $m=2 \\mathrm{kg}$ 、半径为 $R=2 \\mathrm{m}$ 的薄圆盘，可绕通过其一直径的光滑固定轴 $A A "$ 转动，转动惯量 $J=m R^{2}{\\big/}4$ 。该圆盘从静止开始在恒力矩$M=10 0 \\mathrm{N\\cdotm}$ 作用下转动，则 $t=3\\,\\mathrm{s}$ 秒后位于圆盘边缘上与轴 AA''的垂直距离为 R的B点的切向加速度的大小 $a_{t}=$ $\\mathrm{m}/\\mathrm{s}^{2}$ 。 (两位有效数字)', '[]'::jsonb, '$25$', '[]'::jsonb, NULL, NULL, NULL, '$\\beta=M/J=100/(\\frac{1}{4}\\cdot2\\cdot2^2)=25\\,\\mathrm{rad/s^2}$。切向加速度 $a_t=\\beta R=25\\times2=50\\,\\mathrm{m/s^2}$。', NULL, NULL, '/physics/q024.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-025', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 25 题', '如图，质量为m长为 $l=0.2 \\mathrm{m}$ 的均匀细杆，放在倾角为 $\\alpha=30^{\\circ}$ 光滑斜面上，可以绕通过杆上端且与斜面垂直的光滑轴O在斜面上转动。要使此杆能绕轴转动一周，则杆的最小初始角速度 $\\omega_{0}=$ _rad/s。(重力加速度为 $9.8 \\mathrm{m}/\\mathrm{s}^{2}$ ，结果保留两位有效数字)', '[]'::jsonb, '$3.1$', '[]'::jsonb, NULL, NULL, NULL, '由机械能守恒，$\\frac{1}{2}J\\omega_0^2\\ge 2mgl\\sin\\alpha$，$J=\\frac{1}{3}ml^2$，得 $\\omega_0\\ge\\sqrt{12g\\sin\\alpha/l}\\approx3.07\\,\\mathrm{rad/s}$，取 $3.1\\,\\mathrm{rad/s}$。', NULL, NULL, '/physics/q025.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-026', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 26 题', '在光滑的水平面上，一根长 L＝2 m 的绳子，一端固定于 O 点，另一端系一质量 m＝0.5 kg的物体．开始时，物体位于位置 A，OA间距离 $d {=}0.5 \\mathrm{m}$ ，绳子处于松弛状态．现在使物体以初速度 $v_{A}{=}4 \\mathrm{m}{\\cdot}\\mathrm{s}^{-1}$ 垂直于 OA 向右滑动，如图所示．设以后的运动中物体到达位置B,此时物体速度的方向与绳垂直．则此时刻物体对O点的角动量的大小 $L_{B}=$ ，物体速度的大小 v＝', '[]'::jsonb, '$1.0\\ \\mathrm{kg\\cdot m^2/s}$; $1.0\\ \\mathrm{m/s}$', '[]'::jsonb, NULL, NULL, NULL, '角动量守恒：$L_B=mv_Ad=0.5\\times4\\times0.5=1.0\\,\\mathrm{kg\\cdot m^2/s}$。在 B 点 $r=L=2\\,\\mathrm{m}$，故 $v=L_B/(mL)=1.0\\,\\mathrm{m/s}$。', NULL, NULL, '/physics/q026.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-027', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 27 题', '用一根长度为 $L=3.2$ 米的细线悬挂一质量为m的小球，线所能承受的最大张力为$T=1.5 m g$ 。现在把线拉至水平位置然后由静止放开，若线断后小球的落地点C恰好在悬点 O 的正下方，如图所示。则高度OC = (两位有效数字)', '[]'::jsonb, '$0.8\\ \\mathrm{m}$', '[]'::jsonb, NULL, NULL, NULL, '下摆到最低点速度 $v=\\sqrt{2gL}$。此时张力 $T=mg+mv^2/L=5mg>1.5mg$，说明线在某处断裂。设线与水平成 $\\theta$ 时张力达 $1.5mg$，由 $T=mg\\sin\\theta+mv^2/L$ 及能量守恒 $v^2=2gL\\sin\\theta$，得 $\\sin\\theta=0.25$，$v^2=0.5gL$。断后水平抛，落 O 正下方，$OC=L\\sin\\theta+\\frac{v^2\\cos^2\\theta}{2g\\sin\\theta}\\approx0.8\\,\\mathrm{m}$。', NULL, NULL, '/physics/q027.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-028', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 28 题', '如图所示，在地面上固定一半径为 $R=0.5\\,\\mathrm{m}$ 的光滑球面，球面顶点A处放一质量为 $7.0\\,\\mathrm{kg}$ 的滑块。一质量为 $m=0.2\\,\\mathrm{kg}$ 的油灰球，以水平速度 $v_{0}=10.5\\,\\mathrm{m/s}$ 射向滑块，并粘附在滑块上一起沿球面下滑。则他们脱离球面时所成的角度 $\\theta=$ rad，(重力加速度 $g=9.8 \\mathrm{m}/\\mathrm{s}^{2}$ ，结果保留两位有效数字)', '[]'::jsonb, '$1.1$', '[]'::jsonb, NULL, NULL, NULL, '水平动量守恒：$mv_0=(M+m)v_1$，$v_1=0.3\\,\\mathrm{m/s}$。脱离时 $N=0$，由机械能守恒与向心力公式得 $\\cos\\theta=\\frac{2}{3}+\\frac{v_1^2}{3gR}\\approx0.46$，$\\theta\\approx1.1\\,\\mathrm{rad}$。', NULL, NULL, '/physics/q028.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-029', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 29 题', '一长为 $l ,$ 、质量可以忽略的直杆，两端分别固定有质量为 $2 m$ 和m的小球，杆可绕通过其中 O 且与杆垂直的水平光滑固定轴在铅直平面内转动．开始杆与水平方向成某一角度 $\\theta$ ，处于静止状态，如图所示．释放后，杆绕O轴转动．则当杆转到水平位置时，该系统所受到的合外力矩的大小 $M=$ _，此时该系统角加速度的大小 $\\beta=$', '[]'::jsonb, '$mgl$; $\\frac{2g}{3l}$', '[]'::jsonb, NULL, NULL, NULL, '水平位置时两球力臂均为 $l/2$，力矩 $M=2m\\cdot g\\cdot l/2 - m\\cdot g\\cdot l/2 = mgl/2$（方向一致），合计 $mgl$。转动惯量 $J=2m(l/2)^2+m(l/2)^2=\\frac{3}{4}ml^2$，$\\beta=M/J=\\frac{2g}{3l}$。', NULL, NULL, '/physics/q029.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-030', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 30 题', '长为l的杆如图悬挂．O为水平光滑固定转轴，平衡时杆竖直下垂，一子弹水平地射入杆中．则在此过程中， 系统对转轴O 的 _守恒．', '[]'::jsonb, '子弹和杆; 角动量', '[]'::jsonb, NULL, NULL, NULL, '子弹射入杆的过程时间极短，轴处冲力产生外力矩可忽略，系统对 O 轴的角动量守恒。', NULL, NULL, '/physics/q030.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-031', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 31 题', '一水平的匀质圆盘，可绕通过盘心的竖直光滑固定轴自由转动．圆盘质量为M，半径为R，对轴的转动惯量 $J {=}\\frac{1}{2}M R^{2}$ ．当圆盘以角速度 $\\omega_{0}$ 转动时，有一质量为m的子弹沿盘的直径方向射入而嵌在盘的边缘上．子弹射入后，圆盘的角速度 $\\omega=$ ·', '[]'::jsonb, '$\\frac{M\\omega_0}{M+2m}$', '[]'::jsonb, NULL, NULL, NULL, '角动量守恒：$J\\omega_0=(J+mR^2)\\omega$，代入 $J=MR^2/2$ 得 $\\omega=M\\omega_0/(M+2m)$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-032', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 32 题', '一长为l质量可以忽略的直杆，可绕通过其一端的水平光滑轴在竖直平面内作定轴转动，在杆的另一端固定着一质量为m的小球，如图所示．现将杆由水平位置无初转速地释放．则杆刚被释放时的角加速度 $\\beta_{0}$ = _，杆与水平方向夹角为 $60^{\\circ}$ 时的角加速度 $\\beta=$', '[]'::jsonb, '$\\frac{g}{l}$; $\\frac{g}{2l}$', '[]'::jsonb, NULL, NULL, NULL, '$M=mgl\\cos\\phi$，$J=ml^2$，$\\beta=M/J=g\\cos\\phi/l$。水平时 $\\phi=0$，$\\beta_0=g/l$；$60^\\circ$ 时 $\\cos\\phi=1/2$，$\\beta=g/(2l)$。', NULL, NULL, '/physics/q032.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-033', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 33 题', '如图，用传送带A输送煤粉，料斗口在A上方高 $h=0.5 \\mathrm{m}$ 处，煤粉自料斗口自由落在A上．设料斗口连续卸煤的流量为 $q_{m}=40$ kg/s ，A 以 $v{=}2.0 \\mathrm{m/s}$ 的水平速度匀速向右移动．求装煤的过程中，煤粉对A的作用力的大小和方向．(不计相对传送带静止的煤粉质重)', '[]'::jsonb, '$F\\approx 1.49\\times 10^2\\,\\mathrm{N}$；方向与水平方向夹角约 $57.4^{\\circ}$，斜向左下方', '[]'::jsonb, NULL, NULL, NULL, '单位时间内落在传送带上的煤粉在水平方向动量变化产生水平力 $F_x=q_m v$，竖直方向动量变化产生竖直力 $F_y=q_m\\sqrt{2gh}$。煤粉对传送带的作用力为这两个反作用力的合力，大小 $F=\\sqrt{F_x^2+F_y^2}=q_m\\sqrt{v^2+2gh}\\approx 1.49\\times 10^2\\,\\mathrm{N}$，方向与水平方向夹角 $\\theta=\\arctan\\frac{\\sqrt{2gh}}{v}\\approx 57.4^{\\circ}$，斜向左下方。', NULL, NULL, '/physics/q033.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-034', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 34 题', '一升降机内有一倾角为α的固定光滑斜面，如图所示。当升降机以匀加速度 $\\vec{a}_{0}$ 上升时，质量为m的物体A沿斜面滑下，试以升降机为参考系，求A对地面的加速度 $\\vec{a}$ .', '[]'::jsonb, '$a=\\sqrt{g^2+a_0^2-2ga_0\\cos\\alpha}$；方向沿斜面向下与水平方向夹角 $\\arctan\\frac{g\\sin\\alpha}{g\\cos\\alpha-a_0}$', '[]'::jsonb, NULL, NULL, NULL, '以升降机为参考系，物体受重力 $m\\vec g$、惯性力 $-m\\vec a_0$ 和斜面支持力。沿斜面方向合力 $F=m(g\\sin\\alpha-a_0\\sin\\alpha)$ 有误，应为 $m\\sqrt{g^2+a_0^2}$ 的合力沿斜面分量。正确：等效重力 $\\vec g'' = \\vec g - \\vec a_0$，沿斜面加速度 $a''=g\\sin\\alpha-a_0\\sin\\alpha$ 当 $\\vec a_0$ 竖直向上时。A 对地加速度 $\\vec a=\\vec a''+\\vec a_0$。', NULL, NULL, '/physics/q034.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-035', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 35 题', '一根特殊弹簧，在伸长 x 米时，其弹力为 $4 x+6 x^{2}$ 牛顿。

(1)试求把弹簧从 x=0.5m 米拉长到 $x {=}1.0 \\mathrm{m}$ 米时，外力克服弹簧力所作的总功。

(2)将弹簧的一端固定，在其另一端拴一质量为2千克的静止物体，试求弹簧从$x {=}1.0$ 米回到x=0.5米时物体的速率。(不计重力)', '[]'::jsonb, '$W=1.75\\,\\mathrm{J}$; $v=\\sqrt{1.75}\\approx1.32\\,\\mathrm{m/s}$', '[]'::jsonb, NULL, NULL, NULL, '（1）$W=\\int_{0.5}^{1.0}(4x+6x^2)\\,dx=[2x^2+2x^3]_{0.5}^{1.0}=4-0.625=1.75\\,\\mathrm{J}$。（2）弹性势能转化为动能：$\\frac{1}{2}mv^2=W$，$v=\\sqrt{2W/m}=\\sqrt{1.75}\\approx1.32\\,\\mathrm{m/s}$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-036', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 36 题', '两个滑冰运动员A、B的质量均为 $m {=}70 \\mathrm{kg}$ ，以 $v_{0}=6.5 \\mathrm{m}/\\mathrm{s}$ 的速率沿相反方向滑行，滑行路线间的垂直距离为 $R=10 \\mathrm{m}$ ，当彼此交错时，各抓住10 m绳索的一端，然后相对旋转,

(1) 在抓住绳索之前，各自对绳中心的角动量是多少？抓住后又是多少？

(2)他们各自收拢绳索，到绳长为r =5 m时，各自的速率如何？

(3)绳长为5 m时，绳内的张力多大？

(4)二人在收拢绳索时，设收绳速率相同，问二人各做了多少功？', '[]'::jsonb, '$L=2275\\,\\mathrm{kg\\cdot m^2/s}$; $v=13\\,\\mathrm{m/s}$; $T=4810\\,\\mathrm{N}$; $W=4436\\,\\mathrm{J}$', '[]'::jsonb, NULL, NULL, NULL, '（1）$L=mv_0R/2=70\\times6.5\\times5=2275\\,\\mathrm{kg\\cdot m^2/s}$，抓住前后角动量不变。（2）$mvr/2=L$，$v=2L/(mr)=13\\,\\mathrm{m/s}$。（3）$T=mv^2/(r/2)=4810\\,\\mathrm{N}$。（4）$W=\\frac{1}{2}mv^2-\\frac{1}{2}mv_0^2=4436\\,\\mathrm{J}$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-037', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 37 题', '一条轻绳跨过一轻滑轮(滑轮与轴间摩擦可忽略)，在绳的一端挂一质量为 $m_{1}$ 的物体，在另一侧有一质量为 $m_{2}$ 的环，求当环相对于绳以恒定的加速度 $a_{2}$ 沿绳向下滑动时，物体和环相对地面的加速度各是多少？环与绳间的摩擦力多大？', '[]'::jsonb, '$a_1=\\frac{(m_1-m_2)a_2+m_1g}{m_1+m_2}$ 向下; $a_{2地}=a_2-a_1$ 向下; $f=\\frac{2m_1m_2g+m_1m_2a_2}{m_1+m_2}$', '[]'::jsonb, NULL, NULL, NULL, '设物体向下加速度为 $a_1$，绳张力 $T$，环受摩擦力 $f$ 向上。对物体：$m_1g-T=m_1a_1$；对环：$m_2g-f=m_2a_{2地}$，$a_{2地}=a_2-a_1$，$T=f$。联立求解。', NULL, NULL, '/physics/q037.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-038', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 38 题', '质量分别为m和2m 、半径分别为r 和2r 的两个均匀圆盘，同轴地粘在一起，可以绕通过盘心且垂直盘面的水平光滑固定轴转动，对转轴的转动惯量为 $9 m r^{2}/2$ ，大小圆盘边缘都绕有绳子，绳子下端都挂一质量为m的重物，如图所示．求盘的角加速度的大小．', '[]'::jsonb, '$\\beta=\\frac{2g}{19r}$', '[]'::jsonb, NULL, NULL, NULL, '设左侧重物加速度 $a_1$ 向下，右侧 $a_2$ 向下。转动定律：$T_1\\cdot2r-T_2\\cdot r=J\\beta$；重物：$mg-T_1=ma_1$，$mg-T_2=ma_2$；$a_1=2r\\beta$，$a_2=r\\beta$。联立得 $\\beta=2g/(19r)$。', NULL, NULL, '/physics/q038.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-039', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 39 题', '一质量为M ，长为l的均匀细直杆，可绕通过其中心且与杆垂直的光滑水平固定轴，在竖直平面内转动。当杆停止于竖直位置时，质量为m的子弹沿水平方向射入杆的下端且留在杆内，并使杆摆动，若杆摆动的最大偏角为θ，试求：(1)入射前的速率 $v_{0}$ ；(2)在最大偏角θ时，杆转动的角加速度。', '[]'::jsonb, '$v_0=\\frac{1}{m}\\sqrt{\\frac{(M+3m)(M+6m)}{6}gl(1-\\cos\\theta)}$; $\\beta=\\frac{3(M+2m)g\\sin\\theta}{(M+3m)l}$', '[]'::jsonb, NULL, NULL, NULL, '（1）角动量守恒：$mv_0(l/2)=J_{总}\\omega_0$，$J_{总}=Ml^2/12+m(l/2)^2$。机械能守恒求 $\\omega_0$ 与 $\\theta$ 关系，解出 $v_0$。（2）$\\beta=M/J_{总}$，$M=(Mg\\cdot l/2+mg\\cdot l/2)\\sin\\theta$。', NULL, NULL, '/physics/q039.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-040', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 40 题', '一质量均匀分布的圆盘，质量为M ，半径为R，放在一粗糙水平面上(圆盘与水平面之间的摩擦系数为 $\\mu$ )，圆盘可绕通过其中心O的竖直固定光滑轴转动．开始时，圆盘静止，一质量为m的子弹以水平速度 $v_{0}$ 垂直于圆盘半径打入圆盘边缘并嵌在盘边上，求(1)子弹击中圆盘后，盘所获得的角速度；(2)经过多少时间后，圆盘停止转动(圆盘绕通过O的竖直轴的转动惯量为 $\\frac{1}{2}M R^{2}$ ，忽略子弹重力造成的摩擦阻力矩)。', '[]'::jsonb, '$\\omega=\\frac{2mv_0}{(M+2m)R}$; $t=\\frac{3(M+2m)v_0}{4\\mu Mg}$', '[]'::jsonb, NULL, NULL, NULL, '（1）角动量守恒：$mv_0R=(\\frac{1}{2}MR^2+mR^2)\\omega$，得 $\\omega$。（2）摩擦力矩 $M_f=\\int_0^R \\mu(Mg/\\pi R^2)2\\pi r^2\\,dr=\\frac{2}{3}\\mu MgR$。由 $M_f t=J_{总}\\omega$ 得 $t$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-041', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 41 题', '一车轮可绕通过轮心O且与轮面垂直的水平光滑固定轴，在竖直面内转动，轮的质量为M，可以认为均匀分布在半径为R的圆周上，绕O轴的转动惯量J＝$M R^{2}$ ．车轮原来静止，一质量为 m 的子弹，以速度 $v_{0}$ 沿与水平方向成α 角度射中轮心O正上方的轮缘A处，并留在A处，如图所示．设子弹与轮撞击时间极短．问：

(1)以车轮、子弹为研究系统，撞击前后系统的动量是否守恒？为什么？动能是否守恒？为什么？角动量是否守恒？为什么？

(2)子弹和轮开始一起运动时，轮的角速度是多少？', '[]'::jsonb, '动量不守恒（轴处受外力冲量）; 动能不守恒（完全非弹性碰撞）; 角动量守恒（轴处外力矩为零）; $\\omega=\\frac{mv_0\\cos\\alpha}{(M+m)R}$', '[]'::jsonb, NULL, NULL, NULL, '（1）轴 O 对轮有约束冲力，系统动量不守恒；碰撞为非弹性，动能不守恒；轴处力过 O 点，对 O 力矩为零，角动量守恒。（2）$mv_0\\cos\\alpha\\cdot R=(MR^2+mR^2)\\omega$。', NULL, NULL, '/physics/q041.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-042', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 42 题', '一长为 1 m 的均匀直棒可绕过其一端且与棒垂直的水平光滑固定轴转动．抬起另一端使棒向上与水平面成 $60^{\\circ}$ ，然后无初转速地将棒释放．已知棒对轴的转动惯量为 $\\frac{1}{3}ml^{2}$ ，其中 m 和 l 分别为棒的质量和长度．求：

(1)放手时棒的角加速度；

(2)棒转到水平位置时的角加速度', '[]'::jsonb, '$\\beta_0=\\frac{3g}{4l}=7.35\\,\\mathrm{rad/s^2}$; $\\beta=\\frac{3g}{2l}=14.7\\,\\mathrm{rad/s^2}$', '[]'::jsonb, NULL, NULL, NULL, '（1）$M=mg\\frac{l}{2}\\cos60^\\circ=\\frac{1}{4}mgl$，$\\beta_0=M/J=\\frac{3g}{4l}$。（2）水平位置 $M=\\frac{1}{2}mgl$，$\\beta=\\frac{3g}{2l}$。', NULL, NULL, '/physics/q042.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-043', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 43 题', '两个大小不同、具有水平光滑轴的定滑轮，顶点在同一水平线上。小滑轮的质量为 m，半径为 r，对轴的转动惯量 $J=\\frac{1}{2}m r^{2}$ 。大滑轮的质量 $m {''}{=}2 m$ ，半径 $r^{\\prime}{=}2 r$ ，对轴的转动惯量 $J^{\\prime}=\\frac{1}{2}m^{\\prime}{r^{\\prime}}^{2}$ 。一根不可伸长的轻质细绳跨过这两个定滑轮，绳的两端分别挂着物体 A和 B。A的质量为 m，B的质量 $m {''}{=}2 m$ 。这一系统由静止开始转动。已知 $m {=}6.0 \\mathrm{kg}$ ， $r {=}5.0 \\mathrm{cm}$ 。求两滑轮的角加速度和它们之间绳中的张力。', '[]'::jsonb, '$\\beta_A=\\frac{4g}{17r}\\approx46\\,\\mathrm{rad/s^2}$; $\\beta_B=\\frac{2g}{17r}\\approx23\\,\\mathrm{rad/s^2}$; $T=\\frac{12mg}{17}\\approx41.3\\,\\mathrm{N}$', '[]'::jsonb, NULL, NULL, NULL, '设绳中张力为 $T$，A 向上加速度 $a$，B 向下加速度 $a$。对小滑轮：$(T-T_1)r=J\\beta_A$；对大滑轮：$(T_2-T)r''=J''\\beta_B$；物体：$T_1-mg=ma$，$2mg-T_2=2ma$；$a=r\\beta_A=r''\\beta_B$。联立解得。', NULL, NULL, '/physics/q043.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-001', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 0, '第 1 题', '在双缝干涉实验中,若单色光源 S到两缝 $S _ { 1 } .$ 、 $S _ { 2 }$ 距离相等,则观察屏上中央明纹位于图中 O 处。现将光源 S 向下移动到示意图中的 S 位置,则', '["中央明条纹也向下移动,且条纹间距不变","中央明条纹向上移动,且条纹间距不变","中央明条纹向下移动,且条纹间距增大","中央明条纹向上移动,且条纹间距增大。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-01-training/e1934e63bf306ca25fbb91acd5f30b8755998ecd384ef93baf72a05af2e134c7.jpg', 1, '["选择题"]'::jsonb, '波动光学练习一.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-002', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 0, '第 2 题', '用白光光源进行双缝实验,若用一个纯红色的滤光片遮盖一条缝,用一个纯蓝色的滤光片遮盖另一条缝,则', '["干涉条纹的宽度将发生改变","产生红光和蓝光的两套彩色干涉条纹","干涉条纹的亮度将发生改变","不产生干涉条纹。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习一.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-003', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 0, '第 3 题', '在双缝干涉实验中,两缝间距离为 d,双缝与屏幕之间的距离为 $D \\ ( D { > } { > } d )$ 。波长为 λ 的平行单色光垂直照射到双缝上。屏幕上干涉条纹中相邻暗纹之间的距离是', '["$2 \\\\lambda D / d$","$\\\\lambda d / D$","$d D / \\\\lambda$","$\\\\lambda D / d$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习一.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-004', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 2, '第 4 题', '在双缝干涉实验中,若两缝的间距为所用光波波长的 N 倍,观察屏到双缝的距离为D,则屏上相邻明纹的间距为 。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习一.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-005', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 2, '第 5 题', '在双缝干涉实验中,双缝间距为 d,双缝到屏的距离为 D( $( D { > } { > } d )$ ,测得中央零级明纹与第五级明之间的距离为 x,则入射光的波长为C', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习一.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-006', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 2, '第 6 题', '( tk1000A000009334 ) 在 双 缝 干 涉 实 验 中 , 所 用 单 色 光 波 长 为$\\lambda = 5 6 2 . 5 \\mathrm { n m } \\big ( \\mathrm { l n m } = 1 0 ^ { - 9 } \\mathrm { m } \\big )$ ,双缝与观察屏的距离 $D { = } 1 . 2 \\mathrm { m }$ ,若测得屏上相邻明条纹间距为 $\\Delta x = 1 . 5 \\mathrm { m m }$ ,则双缝的间距d=', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习一.pdf 第6题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-007', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 3, '第 7 题', '在图示的双缝干涉实验中,若用薄玻璃片(折射率 $n _ { 1 } { = } 1 . 4 )$ 覆盖缝 $S _ { 1 }$ ,用同样厚度的玻璃片(但折射率 $n _ { 2 } { = } 1 . 7 )$ )覆盖缝 $S _ { 2 } ,$ ,将使原来未放玻璃 时 屏 上 的 中 央 明 条 纹 处 O 变 为 第 五 级 明 纹 。 设 单 色 光 波 长$\\lambda = 4 8 0 \\mathrm { n m } \\big ( \\mathrm { l n m } = 1 0 ^ { - 9 } \\mathrm { m } \\big )$ ,求玻璃片的厚度d(可认为光线垂直穿过玻璃片)。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-01-training/ac2a9ae924f795ee24739fb2373236ebe61b531e1fb8aa2ce1c1d629f0612e8d.jpg', 1, '["计算题"]'::jsonb, '波动光学练习一.pdf 第7题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-008', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 3, '第 8 题', '( js1000A000008966 ) 薄 钢 片 上 有 两 条 紧 靠 的 平 行 细 缝 , 用 波 长$\\lambda = 5 4 6 . \\mathrm { l n m } \\big ( \\mathrm { l n m } = 1 0 ^ { - 9 } \\mathrm { m } \\big )$ 的平面光波正入射到钢片上。屏幕距双缝的距离为$D { = } 2 . 0 0 \\mathrm { m }$ ,测得中央明条纹两侧的第五级明条纹间的距离为 $\\Delta x = 1 2 . 0 \\mathrm { m m }$ 。求两缝间的距离;
(2)从任一明条纹(记作0)向一边数到第20条明条纹,共经过多大距离？
(3)如果使光波斜入射到钢片上,条纹间距将如何改变？', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '波动光学练习一.pdf 第8题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-001', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 0, '第 1 题', '如图所示,折射率为 $n _ { 2 } .$ 、厚度为 e的透明介质薄膜的上方和下方的透明介质的折射率分别为 $n _ { 1 }$ 和 $n _ { 3 }$ ,已知 $n _ { 1 } { < } n _ { 2 } { < } n _ { 3 }$ 。若用波长为 λ 的单色平行光垂直入射到该薄膜上,则从薄膜上、下两表面反射的光束① 与② 的光程差是', '["$2 \\\\mathbf { n } _ { 2 } \\\\ \\\\mathbf { e }$","$2 n , e - \\\\lambda / 2$","$2 n _ { \\\\mathrm { { > } } } e - \\\\lambda$","$2 n _ { 2 } e - \\\\lambda / \\\\left( 2 n _ { 2 } \\\\right)$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-02-training/3215a92dd2998b600310a215340499e5fda0f6b07d0cfe4f7dcbe2c71250b07f.jpg', 1, '["选择题"]'::jsonb, '波动光学练习二.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-002', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 0, '第 2 题', '一束波长为 λ 的单色光由空气垂直入射到折射率为 n 的透明薄膜上,透明薄膜放在空气中,要使反射光得到干涉加强,则薄膜最小的厚度为', '["λ/4","$\\\\lambda / { \\\\left( 4 n \\\\right) }$","$\\\\lambda / 2$","$\\\\lambda / { \\\\left( 2 n \\\\right) }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习二.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-003', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 2, '第 3 题', '如图所示,假设有两个同相的相干点光源 $S _ { 1 }$ 和 $S _ { 2 }$ ,发出波长为 λ 的光。A 是它们连线的中垂线上的一点。若在 $S _ { 1 }$ 与 A 之间插入厚度为 e、折射率为 n 的薄玻璃片,则两光源发出的光在 A 点的相位差 $\\Delta \\phi =$ \\_。若已知 $\\lambda = 5 0 0 \\mathrm { n m }$ $n { = } 1 . 5$ ,A点恰为第四级明纹中心,则 $e = { \\mathrm { ~ \\textrm ~ { ~ ~ } ~ } } { \\mathrm { n m } } _ { \\beta }$', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-02-training/18f3b401316c99fd4c7458f1da3eb568c451ca409cc9676d726b7a5f42a599b7.jpg', 1, '["填空题"]'::jsonb, '波动光学练习二.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-004', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 2, '第 4 题', '一束波长为 $\\lambda = 6 0 0 \\mathrm { n m \\ : \\ : ( \\ l n m { = } 1 0 ^ { - 9 } m ) }$ 的平行单色光垂直入射到折射率为 n=1.33 的透明薄膜上,该薄膜是放在空气中的。要使反射光得到最大限度的加强,薄膜最小厚度应为 nm。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习二.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-005', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 2, '第 5 题', '波长为 λ 的平行单色光垂直照射到折射率为 n 的劈形膜上,相邻的两明纹所对应的薄膜厚度之差是 C', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习二.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-006', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 3, '第 6 题', '用波长为 $5 0 0 \\mathrm { n m } ~ ( 1 \\mathrm { n m } { = } 1 0 ^ { - 9 } \\mathrm { m } )$ 的单色光垂直照射到由两块光学平玻璃构成的空气劈形膜上。在观察反射光的干涉现象中,距劈形膜棱边$l { = } 1 . 5 6 \\mathrm { c m }$ 的A处是从棱边算起的第四条暗条纹中心。求此空气劈形膜的劈尖角θ;
(2)改用 600nm 的单色光垂直照射到此劈尖上仍观察反射光的干涉条纹,A 处是明条纹还是暗条纹？
(3)在第(2)问的情形从棱边到A处的范围内共有几条明纹？几条暗纹？', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '波动光学练习二.pdf 第6题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-007', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 3, '第 7 题', '波长 =650nm 的红光垂直照射到劈形液膜上,膜的折射率n=1.33,液面两侧是同一种媒质。观察反射光的干涉条纹。离开劈形膜棱边的第一条明条纹中心所对应的膜厚度是多少？
(2)若相邻的明条纹间距 l=6mm,上述第一条明纹中心到劈形膜棱边的距离 x 是多少？', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '波动光学练习二.pdf 第7题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-001', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 0, '第 1 题', '在图示三种透明材料构成的牛顿环装置中,用单色光垂直照射,在反射光中看到干涉条纹,则在接触点P处形成的圆斑为', '["全明","全暗","右半部明,左半部暗","右半部暗,左半部明。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-03-training/1282d6ac8a85a1a2039fdb78cf2190437b40cf910ea71d25fe6ba4204f0dc890.jpg', 1, '["选择题"]'::jsonb, '波动光学练习三.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-002', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 0, '第 2 题', '如图 a所示,一光学平板玻璃 A与待测工件 B之间形成空气劈尖,用波长 $\\lambda = 5 0 0 \\mathrm { n m } \\big ( \\mathrm { l n m } = 1 0 ^ { - 9 } \\mathrm { m } \\big )$ 的单色光垂直照射。看到的反射光的干涉条纹如图 b 所示。有些条纹弯曲部分的顶点恰好与其右边条纹的直线部分的连续相切。则工件的上表面缺陷是', '["不平处为凸起纹,最大高度为500nm","不平处为凸起纹,最大高度为250nm","不平处为凹槽,最大深度为500nm","不平处为凹槽,最大深度为250nm。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-03-training/2e64a0cd21b73d61affd67eaecafc6d9291577c8e8ca2bfd26af5a2c5122efc5.jpg', 1, '["选择题"]'::jsonb, '波动光学练习三.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-003', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 2, '第 3 题', '一平凸透镜,凸面朝下放在一平玻璃板上。透镜刚好与玻璃板接触。波长分别为 $\\lambda _ { 1 } = 6 0 0 \\mathrm { n m }$ 和 $\\lambda _ { 2 } = 5 0 0 \\mathrm { n m }$ 的两种单色光垂直入射,观察反射光形成的牛顿环。从中心向外数的两种光的第五个明环所对应的空气膜厚度之差为 nm。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习三.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-004', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 2, '第 4 题', '已知在迈克耳孙干涉仪中使用波长为 λ 的单色光。在干涉仪的可动反射镜移动距离d的过程中,干涉条纹将移动 \\_条。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习三.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-005', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 2, '第 5 题', '用迈克耳孙干涉仪产生等厚干涉条纹,设入射光的波长为,在反射镜 $M _ { 2 }$ 转动过程中,在总的观测区域宽度 L 内,观测到总的干涉条纹数从 $N _ { 1 }$ 条增加到 $N _ { 2 }$ 条。在此过程中 $M _ { 2 }$ 转过的角度Δ 是', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习三.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-006', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 3, '第 6 题', '用波长 $\\lambda { = } 5 0 0 n m$ 的单色光照射在有两块玻璃板(一端刚好接触成劈棱)构成的空气劈形膜上,劈尖角 $\\theta { = } 2 { \\times } 1 0 ^ { - 4 } r a d$ 。如果劈形膜内充满折射率为n=1.40的液体,求从劈棱数起第五个明条纹在充入液体前后移动的距离。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '波动光学练习三.pdf 第6题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-007', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 3, '第 7 题', '在牛顿环装置的平凸透镜和平玻璃板之间充以折射率 $n { = } 1 . 3 3$ 的液体(透镜和平玻璃板的折射率都大于 1.33)。凸透镜曲率半径为 300cm,用波长 $\\lambda = 6 5 0 \\mathrm { { n m } }$ 的光垂直照射,求第 10个暗环的半径(设凸透镜中心刚好与平板接触,中心暗斑不计入环数)。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-03-training/7a71df1c7c9b8f8ff151afe7fcdec7393ef4d5843d87556401324040c150a154.jpg', 1, '["计算题"]'::jsonb, '波动光学练习三.pdf 第7题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-04-training-001', 'p1b-m2-04-training', 'physics-b-1', 'p1b-m2', 0, '第 1 题', '在如图所示的单缝夫琅禾费衍射装置中,设中央明纹的衍射角范围很小,若使单缝宽度 a 变为原来的 $\\frac { 3 } { 2 }$ ,同时使入射的单色光的波长 变成原来的 $\\frac 3 4$ ,则屏幕C上单缝衍射条纹中央明纹的宽度Δx将变为原来的', '["3/4倍","2/3倍","9/8倍","1/2倍"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-04-training/06c9dfb5d60bf0262ec3105ddd7cdb190d7310ad1c16d8ac65d5256f1b8dfef3.jpg', 1, '["选择题"]'::jsonb, '波动光学练习四.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
