INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-04-training-003', 'p1b-m2-04-training', 'physics-b-1', 'p1b-m2', 0, '第 3 题', '如果单缝夫琅禾费衍射的第一级暗纹发生在衍射角为$\\varphi = 3 0 ^ { \\circ }$ 的方位上。所用单色光波长为 $\\lambda = 5 0 0 \\mathrm { n m }$ ,则单缝宽度为', '["$2 . 5 { \\\\times } 1 0 ^ { - 5 } \\\\mathrm { m }$","$1 . 0 { \\\\times } 1 0 ^ { - 5 } \\\\mathrm { m }$","$1 . 0 { \\\\times } 1 0 ^ { - 6 } \\\\mathrm { m }$","$2 . 5 { \\\\times } 1 0 ^ { - 7 } \\\\mathrm { m }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习四.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-04-training-004', 'p1b-m2-04-training', 'physics-b-1', 'p1b-m2', 2, '第 4 题', '将波长为 λ 的平行单色光垂直投射于一狭缝上,若对应于衍射图样的第一级暗纹位置的衍射角的绝对值为 θ,则缝的宽度等于', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习四.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
