INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-04-training-008', 'p1b-m2-04-training', 'physics-b-1', 'p1b-m2', 3, '第 8 题', '波长为 $6 0 0 \\mathrm { n m \\ ( \\ l n m { = } 1 0 ^ { - 9 } m ) }$ 的单色光垂直入射到宽度为a=0.10mm的单缝上,观察夫琅禾费衍射图样,透镜焦距 f=1.0m,屏在透镜的焦平面处。求：中央衍射明条纹的宽度 $\\Delta x _ { 0 }$ ;
