INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-05-training-003', 'p1b-m2-05-training', 'physics-b-1', 'p1b-m2', 0, '第 3 题', '对某一定波长的垂直入射光,衍射光栅的屏幕上只能出现零级和一级主极大,欲使屏幕上出现更高级次的主极大,应该', '["换一个光栅常数较小的光栅","换一个光栅常数较大的光栅","将光栅向靠近屏幕的方向移动","将光栅向远离屏幕的方向移动。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习五.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-05-training-004', 'p1b-m2-05-training', 'physics-b-1', 'p1b-m2', 0, '第 4 题', '在光栅光谱中,假如所有偶数级次的主极大都恰好在单缝衍射的暗纹方向上,因而实际上不出现,那么此光栅每个透光缝宽度 a 和相邻两缝间不透光部分宽度b的关系为', '["$a = { \\\\frac { 1 } { 2 } } b$","$a = b$","$a = 2 b$","$a = 3 b$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习五.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-05-training-005', 'p1b-m2-05-training', 'physics-b-1', 'p1b-m2', 2, '第 5 题', '( tk1000A000009233 ) 用 波 长 为 的 单 色 平 行 红 光 垂 直 在 光 棚 常 数$d = 2 \\mu m \\big ( 1 \\mu m = 1 0 ^ { - 6 } \\mathrm { m } \\big )$ 的光栅上,用焦距 f=0.5m的透镜将光聚在屏上,测得第一级谱 线 与 透 镜 主 焦 点 的 距 离 l=0.1667m 。 则 可 知 该 入 射 的 红 光 波 长= \\_nm。( $\\mathrm { \\Omega _ { 1 n m = 1 0 } ^ { - 9 } m } )$', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习五.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
