INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-05-training-008', 'p1b-m2-05-training', 'physics-b-1', 'p1b-m2', 3, '第 8 题', '在单缝夫琅禾费衍射实验中,垂直入射的光有两种波长,$\\lambda _ { 1 } = 4 0 0 \\mathrm { n m }$ $\\lambda _ { \\gamma } = 7 6 0 \\mathrm { n m }$ 。已知单缝宽度 $a { = } 1 . 0 { \\times } 1 0 ^ { - 2 } \\mathrm { c m }$ ,透镜焦距 $f { = } 5 0 \\mathrm { c m }$ 。求：两种光第一级衍射明纹中心之间的距离;
(2)若用光栅常数 $d { = } 1 . 0 { \\times } 1 0 ^ { - 3 } \\mathrm { c m }$ 的光栅替换单缝,其他条件和上一问相同,求两种光第一级主极大之间的距离。
9 $\\mathrm { ( j s 1 0 0 0 A 0 0 0 0 9 0 7 4 ) }$
氢 放 电 管 发 出 的 光 垂 直 照 射 在 某 光 栅 上 , 在 衍 射 角 $\\varphi = 4 1 ^ { \\circ }$ 的 方 向 上 看 到$\\lambda _ { 1 } = 6 5 6 . 2 \\mathrm { n m }$ 和 $\\lambda _ { 2 } = 4 1 0 . 1 \\mathrm { n m } ( 1 \\mathrm { n m } { = } 1 0 ^ { - 9 } \\mathrm { m } )$ )的谱线相重合,求光栅常数最小是多少？', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '波动光学练习五.pdf 第8题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-06-training-001', 'p1b-m2-06-training', 'physics-b-1', 'p1b-m2', 0, '第 1 题', '一束光是自然光和线偏振光的混合光,让它垂直通过一偏振片。若以此入射光束为轴旋转偏振片,测得透射光强度最大值是最小值的 5 倍,那么入射光束中自然光与线偏振光的光强比值为', '["1/2","1/3","1/4","1/5。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习六.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-06-training-002', 'p1b-m2-06-training', 'physics-b-1', 'p1b-m2', 0, '第 2 题', '在双缝干涉实验中,用单色自然光,在屏上形成干涉条纹。若在两缝后放一个偏振片,则', '["干涉条纹的间距不变,但明纹的亮度加强","干涉条纹的间距不变,但明纹的亮度减弱","干涉条纹的间距变窄,且明纹的亮度减弱","无干涉条纹。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习六.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-06-training-003', 'p1b-m2-06-training', 'physics-b-1', 'p1b-m2', 0, '第 3 题', '一束光强为 $I _ { 0 }$ 的自然光,相继通过三个偏振片 $P _ { 1 } , \\ P _ { 2 } , \\ P _ { 3 }$ 后,出射光的光强为 $I { = } 3 I _ { 0 } / 3 2$ 。已知 $P _ { 1 }$ 和 $P _ { 3 }$ 的偏振化方向相互垂直,若以入射光线为轴,旋转 $P _ { 2 }$ ,要使出射光的光强为零, $P _ { 2 }$ 最少要转过的角度是', '["$6 0 ^ { \\\\circ }$","$3 0 ^ { \\\\circ }$","$9 0 ^ { \\\\circ }$","$4 5 ^ { \\\\circ }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习六.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
