INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m5-001', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-1', 2, '定积分的几何意义', '\\( \\displaystyle \\int_0^1 \\sqrt{1-x^2}\\,dx=\\) __________。', '[]'::jsonb, 'pi/4', '[]'::jsonb, NULL, NULL, NULL, '表示单位圆第一象限面积 \\( \\frac{\\pi}{4} \\)。', NULL, NULL, NULL, 2, '["定积分"]'::jsonb, '高等数学（第六版）', 9) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
