INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-004', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-2', 5, '收敛数列的性质', '收敛数列的极限唯一。', '["正确","错误"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '极限若存在则唯一。', NULL, NULL, NULL, 2, '["数列极限"]'::jsonb, '高等数学（第六版）', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-007', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-2', 5, '无穷小与无穷大', '同一变化过程中的无穷小量的倒数是无穷大量。', '["正确","错误"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '需该无穷小不为零；本题表述不严谨，但通常指非零无穷小。若按教材原意，判断为错误更稳妥，因为未排除恒为零。', NULL, NULL, NULL, 2, '["无穷小"]'::jsonb, '高等数学（第六版）', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m3-007', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-2', 5, '单调性判定', '若 \\( f^{\\prime}(x)>0 \\) 在区间 \\( I \\) 内恒成立，则 \\( f(x) \\) 在 \\( I \\) 上单调递增。', '["正确","错误"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '导数正则函数递增。', NULL, NULL, NULL, 2, '["单调性"]'::jsonb, '高等数学（第六版）', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
