INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m4-005', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-2', 5, '对坐标曲面积分的方向', '对坐标的曲面积分与曲面的侧（方向）无关。', '["正确","错误"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '对坐标的曲面积分与曲面所取的侧有关，改变侧会改变符号。', NULL, NULL, NULL, 2, '["曲面积分"]'::jsonb, '高等数学（第六版）', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
