INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m1-001', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '向量的模', '求向量 \\( \\boldsymbol{a}=(1,2,2) \\) 的模。', '[]'::jsonb, '3', '[]'::jsonb, NULL, 0.000001, NULL, '\\( |\\boldsymbol{a}|=\\sqrt{1^2+2^2+2^2}=3 \\)。', NULL, NULL, NULL, 2, '["向量"]'::jsonb, '高等数学（第六版）', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m1-002', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '数量积', '设 \\( \\boldsymbol{a}=(1,2,3) \\)，\\( \\boldsymbol{b}=(3,2,1) \\)，求 \\( \\boldsymbol{a}\\cdot\\boldsymbol{b} \\)。', '[]'::jsonb, '10', '[]'::jsonb, NULL, 0.000001, NULL, '对应分量相乘求和：\\( 1\\cdot3+2\\cdot2+3\\cdot1=10 \\)。', NULL, NULL, NULL, 2, '["数量积"]'::jsonb, '高等数学（第六版）', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m1-003', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '向量积', '设 \\( \\boldsymbol{a}=(1,0,0) \\)，\\( \\boldsymbol{b}=(0,1,0) \\)，求 \\( \\boldsymbol{a}\\times\\boldsymbol{b} \\)（格式：x,y,z）。', '[]'::jsonb, '0,0,1', '[]'::jsonb, NULL, NULL, NULL, '按行列式计算得 \\( (0,0,1) \\)。', NULL, NULL, NULL, 2, '["向量积"]'::jsonb, '高等数学（第六版）', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m1-006', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '平面方程', '求过点 \\( (1,0,0) \\) 且法向量为 \\( (1,1,1) \\) 的平面方程（写成“x+y+z=1”形式）。', '[]'::jsonb, 'x+y+z=1', '[]'::jsonb, NULL, NULL, NULL, '点法式：\\( 1(x-1)+1(y-0)+1(z-0)=0 \\)，即 \\( x+y+z=1 \\)。', NULL, NULL, NULL, 2, '["平面"]'::jsonb, '高等数学（第六版）', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m1-007', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '空间直线方程', '求过点 \\( (0,0,0) \\) 且方向向量为 \\( (1,2,3) \\) 的直线的对称式方程。', '[]'::jsonb, 'x/1=y/2=z/3', '[]'::jsonb, NULL, NULL, NULL, '对称式 \\( \\frac{x}{1}=\\frac{y}{2}=\\frac{z}{3} \\)。', NULL, NULL, NULL, 2, '["空间直线"]'::jsonb, '高等数学（第六版）', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m1-008', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '距离', '求点 \\( (1,1,1) \\) 到原点的距离。', '[]'::jsonb, '1.732051', '[]'::jsonb, NULL, 0.000001, NULL, '\\( d=\\sqrt{1^2+1^2+1^2}=\\sqrt3 \\)。', NULL, NULL, NULL, 2, '["向量"]'::jsonb, '高等数学（第六版）', 5) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m2-002', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '偏导数', '设 \\( z=x^2y+y^3 \\)，求 \\( \\frac{\\partial z}{\\partial x} \\)。', '[]'::jsonb, '2xy', '[]'::jsonb, NULL, NULL, NULL, '对 \\( x \\) 求导视 \\( y \\) 为常数。', NULL, NULL, NULL, 2, '["偏导数"]'::jsonb, '高等数学（第六版）', 6) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m2-003', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '偏导数 2', '设 \\( z=e^{xy} \\)，求 \\( \\frac{\\partial z}{\\partial y} \\)。', '[]'::jsonb, 'xe^{xy}', '[]'::jsonb, NULL, NULL, NULL, '链式法则。', NULL, NULL, NULL, 2, '["偏导数"]'::jsonb, '高等数学（第六版）', 7) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m2-004', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '全微分', '设 \\( z=x^2+y^2 \\)，求全微分 \\( dz \\)（写成“2xdx+2ydy”）。', '[]'::jsonb, '2xdx+2ydy', '[]'::jsonb, NULL, NULL, NULL, '\\( dz=\\frac{\\partial z}{\\partial x}dx+\\frac{\\partial z}{\\partial y}dy=2x\\,dx+2y\\,dy \\)。', NULL, NULL, NULL, 2, '["全微分"]'::jsonb, '高等数学（第六版）', 8) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m2-005', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '复合函数求导', '设 \\( z=\\sin u \\)，\\( u=x^2+y \\)，求 \\( \\frac{\\partial z}{\\partial x} \\)。', '[]'::jsonb, '2xcos(x^2+y)', '[]'::jsonb, NULL, NULL, NULL, '链式法则：\\( \\frac{\\partial z}{\\partial x}=\\cos u\\cdot2x \\)。', NULL, NULL, NULL, 2, '["复合函数"]'::jsonb, '高等数学（第六版）', 9) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m2-006', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '隐函数求导', '由 \\( x^2+y^2+z^2=1 \\) 确定的隐函数 \\( z=z(x,y) \\)，求 \\( \\frac{\\partial z}{\\partial x} \\) 在 \\( (0,0,1) \\) 处的值。', '[]'::jsonb, '0', '[]'::jsonb, NULL, 0.000001, NULL, '两边对 \\( x \\) 求偏导：\\( 2x+2z z_x=0 \\)，代入得 \\( z_x=0 \\)。', NULL, NULL, NULL, 2, '["隐函数"]'::jsonb, '高等数学（第六版）', 10) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-2-c2-m2-008', 'exam-calculus-2-final', 'exam-calculus-2-final-sec-3', 3, '方向导数', '设 \\( f(x,y)=x^2+y^2 \\)，求在点 \\( (1,0) \\) 沿方向 \\( (1,0) \\) 的方向导数。', '[]'::jsonb, '2', '[]'::jsonb, NULL, 0.000001, NULL, '梯度 \\( \\nabla f=(2x,2y) \\)，方向导数 \\( \\nabla f\\cdot(1,0)=2 \\)。', NULL, NULL, NULL, 2, '["方向导数"]'::jsonb, '高等数学（第六版）', 11) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;

